# -*- coding: utf-8 -*-
"""
BÀI SÁP NHẬP V4.5.2.3 - CHỐT GIAO DIỆN XEM TRƯỚC PHÁT SINH

Mục tiêu nội bộ:
- Không thay đổi nghiệp vụ sáp nhập.
- Không thực hiện sáp nhập.
- Không chủ động ghi phocap.db.
- Không hiển thị mã lỗi kỹ thuật như ACTIVE_STAFF_AT_WRONG_SCHOOL cho người dùng cuối.
- Chuẩn hóa nốt thuật ngữ kỹ thuật và rút gọn danh sách lỗi dài trên màn hình.
"""
from __future__ import annotations
import base64, datetime as dt, hashlib, json, os, py_compile, shutil, traceback
from pathlib import Path

TITLE = "BÀI SÁP NHẬP V4.5.2.3 - CHỐT GIAO DIỆN XEM TRƯỚC PHÁT SINH"
EMBEDDED_FILES = {'app/templates/data_tools/school_merger_future_preview_v45.html': '', 'app/services/school_merger_future_service.py': ''}
EXPECTED_BASE_HASHES = {'app/templates/data_tools/school_merger_future_preview_v45.html': '7e79059482946ba3005af49d3c900ca78990bfb623319e6c74f7957ab1b2f5ab', 'app/services/school_merger_future_service.py': 'e4be6feb1e96911ecd90e4c33786821d4fb0c223e18f9553af39c3c104d86eac'}
FINAL_HASHES = {'app/templates/data_tools/school_merger_future_preview_v45.html': '3699b543baa1081560af0d8eb9ced69fc7df06227c560c4f82f8e33520ed0af5', 'app/services/school_merger_future_service.py': '83460db158345a3cb8ad2354c0ee52302f497e253a3e24a70b79007a934a9881'}

def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def db_fingerprint(db: Path) -> str:
    h = hashlib.sha256()
    for p in [db, Path(str(db)+"-wal"), Path(str(db)+"-shm")]:
        h.update(p.name.encode("utf-8"))
        if p.exists():
            h.update(str(p.stat().st_size).encode("ascii"))
            h.update(sha256_file(p).encode("ascii"))
        else:
            h.update(b"MISSING")
    return h.hexdigest()

def fail(msg: str):
    raise RuntimeError(msg)

def main():
    cwd = Path.cwd().resolve()
    script_dir = Path(__file__).resolve().parent
    root = cwd if (cwd / "app").exists() else script_dir
    if not (root / "app").exists():
        fail(r"Không tìm thấy thư mục app. Hãy chép bộ cài vào C:\PhoCap và chạy tại C:\PhoCap.")
    db = root / "data" / "phocap.db"
    if not db.exists():
        fail(f"Không tìm thấy database: {db}")

    ts = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_chot_giao_dien_phat_sinh_{ts}"
    export_dir = root / "exports" / "Chot_Giao_Dien_Sap_Nhap_Phat_Sinh"
    report_path = export_dir / f"bao_cao_{ts}.json"
    db_before = db_fingerprint(db)
    touched = []

    try:
        for rel in EMBEDDED_FILES:
            p = root / rel
            if not p.exists():
                fail(f"Thiếu tệp nền: {rel}")
            cur = sha256_file(p)
            if cur not in {EXPECTED_BASE_HASHES[rel], FINAL_HASHES[rel]}:
                fail(f"Tệp {rel} không đúng nền đã khóa. SHA hiện tại={cur}")

        backup_dir.mkdir(parents=True, exist_ok=True)
        for rel in EMBEDDED_FILES:
            src = root / rel
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

        for rel, b64 in EMBEDDED_FILES.items():
            p = root / rel
            p.write_bytes(base64.b64decode(b64))
            touched.append(rel)

        for rel, expected in FINAL_HASHES.items():
            got = sha256_file(root / rel)
            if got != expected:
                fail(f"SHA sau cài không đúng: {rel}")

        py_compile.compile(str(root / "app/services/school_merger_future_service.py"), doraise=True)

        preview = (root / "app/templates/data_tools/school_merger_future_preview_v45.html").read_text(encoding="utf-8")
        service = (root / "app/services/school_merger_future_service.py").read_text(encoding="utf-8")
        if "{{ e.code }}" in preview:
            fail("Giao diện vẫn còn hiển thị mã lỗi nội bộ.")
        required = [
            "Dữ liệu hệ thống đủ điều kiện kế thừa",
            "Còn {{ (x.issues|length) - 10 }} lỗi khác",
            "Hãy xử lý các lỗi phía trên.",
            "dữ liệu hệ thống năm nguồn",
        ]
        combined = preview + "\n" + service
        for needle in required:
            if needle not in combined:
                fail(f"Thiếu nội dung chuẩn hóa: {needle}")

        db_after = db_fingerprint(db)
        if db_after != db_before:
            fail("Database/WAL đã thay đổi trong bộ cài. Đã dừng an toàn.")

        export_dir.mkdir(parents=True, exist_ok=True)
        report = {
            "installed_at": dt.datetime.now().isoformat(timespec="seconds"),
            "title_internal": TITLE,
            "database_unchanged": True,
            "backup_dir": str(backup_dir),
            "changes": [
                "Ẩn mã lỗi kỹ thuật nội bộ khỏi màn hình xem trước sáp nhập phát sinh.",
                "Chỉ hiển thị nội dung lỗi bằng tiếng Việt.",
                "Mỗi trường chỉ hiện tối đa 10 lỗi trên màn hình; số lỗi còn lại được báo tổng.",
                "Đổi DB năm nguồn thành dữ liệu hệ thống năm nguồn và rollover thành kế thừa trong thông báo UI.",
                "Không thay đổi logic kiểm tra nguồn, mô phỏng, backup, transaction hay ghi database.",
                "Không chạm chức năng Đổi tên trường.",
            ],
            "files": {rel: {"sha256": FINAL_HASHES[rel]} for rel in EMBEDDED_FILES},
        }
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")

        print()
        print("=" * 108)
        print("CHỐT GIAO DIỆN XEM TRƯỚC SÁP NHẬP PHÁT SINH - CÀI ĐẶT THÀNH CÔNG")
        print("Database: KHÔNG THAY ĐỔI")
        print("Đã ẩn mã lỗi kỹ thuật nội bộ khỏi giao diện.")
        print("Mỗi trường chỉ hiện tối đa 10 lỗi; vẫn giữ nguyên toàn bộ lỗi trong dữ liệu kiểm tra.")
        print("Logic sáp nhập: GIỮ NGUYÊN")
        print("Đổi tên trường: GIỮ NGUYÊN")
        print(f"Backup mã nguồn: {backup_dir}")
        print(f"Báo cáo: {report_path}")
        print("=" * 108)

    except Exception as e:
        try:
            for rel in touched:
                bp = backup_dir / rel
                if bp.exists():
                    p = root / rel
                    p.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(bp, p)
        except Exception:
            pass
        print()
        print("=" * 108)
        print("DỪNG AN TOÀN - CHỐT GIAO DIỆN XEM TRƯỚC SÁP NHẬP PHÁT SINH")
        print("Mã nguồn đã được khôi phục nếu đã chạm file.")
        print(f"Lỗi: {e}")
        print("Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
        print("=" * 108)
        if os.environ.get("PHOCAP_INSTALLER_DEBUG") == "1":
            traceback.print_exc()
        raise SystemExit(1)

if __name__ == "__main__":
    main()
